/*!50003 CREATE*/ /*!50017 DEFINER=`sa`@`%`*/ /*!50003 TRIGGER utrigger_Rera_Complaint_FormN_EventRecord_INSERT AFTER INSERT ON tbl_rera_complaint_formn_eventaction
  FOR EACH ROW
BEGIN      
    DECLARE v_ComplaintId BigInt;      
    Declare v_ComplaintDiaryNumber varchar(100);   
    Declare v_ComplaintEventType int;   
       
      SET v_ComplaintId=NEW.Related_ComplaintorApplication_ID;
      SET v_ComplaintDiaryNumber=NEW.Related_RegDiaryNumber;            
      SET v_ComplaintEventType=NEW.EventAction_Type;

 -- Complaint Form-N Details Incomplete File         
 If v_ComplaintEventType = 440007   
 then      
  update tbl_rera_complaint_formn_regdiarynumber set IsDraft=0 where FormN_RelatedComplaint_ID=v_ComplaintId and ComplaintRegDiaryNumber_Name=v_ComplaintDiaryNumber and IsActive=1 and IsLock=0;   
 
  update tbl_rera_complaint_formn_details set IsLock=0 where ComplaintFormN_ID=v_ComplaintId and IsActive=1 and IsLock=1;
  update tbl_rera_complaint_formn_listenclosuresdocuments set IsLock=0 where ComplainantApplicant_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsLock=1;
  update tbl_rera_complaint_formn_additioncomplainant set IsLock=0 where ComplainantorApplicant_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsLock=1; 
  update tbl_rera_complaint_formn_additionrespondent set IsLock=0 where AdditionRespondentM_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsLock=1;
  update tbl_rera_complaint_formn_document_factsofthecase set IsLock=0 where ComplainantApplicant_RelatedComplaintN_ID=v_ComplaintId and IsActive=1 and IsLock=1;
  
  update tbl_rera_complaint_formn_details set IsDraft=4 where ComplaintFormN_ID=v_ComplaintId and IsActive=1 and IsDraft=5; 
  update tbl_rera_complaint_formn_listenclosuresdocuments set IsDraft=4 where ComplainantApplicant_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsDraft=5; 
  update tbl_rera_complaint_formn_additioncomplainant set IsDraft=4 where ComplainantorApplicant_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsDraft=5; 
  update tbl_rera_complaint_formn_additionrespondent set IsDraft=4 where AdditionRespondentM_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsDraft=5;
  update tbl_rera_complaint_formn_document_factsofthecase set IsDraft=4 where ComplainantApplicant_RelatedComplaintN_ID=v_ComplaintId and IsActive=1 and IsDraft=5;

  -- -- Reminder Scheduler (Emails and SMS)
  call usp_insert_tbl_rera_complaint_formn_reminderscheduler_emails(v_ComplaintId, v_ComplaintDiaryNumber, v_ComplaintEventType);
  call usp_insert_tbl_rera_complaint_formn_reminderscheduler_smsgateway(v_ComplaintId, v_ComplaintDiaryNumber, v_ComplaintEventType);
 end if;
 
 -- Complaint No reply within 15 days          
 If v_ComplaintEventType = 440057   
 then      
  update tbl_rera_complaint_formn_regdiarynumber set IsDraft=1 where FormN_RelatedComplaint_ID=v_ComplaintId and ComplaintRegDiaryNumber_Name=v_ComplaintDiaryNumber and IsActive=1;   
   
  update tbl_rera_complaint_formn_details set IsDraft=1, IsLock=1 where ComplaintFormN_ID=v_ComplaintId and IsActive=1; 
  update tbl_rera_complaint_formn_listenclosuresdocuments set IsDraft=1, IsLock=1 where ComplainantApplicant_RelatedComplaint_ID=v_ComplaintId and IsActive=1; 
  update tbl_rera_complaint_formn_additioncomplainant set IsDraft=1, IsLock=1 where ComplainantorApplicant_RelatedComplaint_ID=v_ComplaintId and IsActive=1; 
  update tbl_rera_complaint_formn_additionrespondent set IsDraft=1, IsLock=1 where AdditionRespondentM_RelatedComplaint_ID=v_ComplaintId and IsActive=1; 
  update tbl_rera_complaint_formn_document_factsofthecase set IsDraft=1, IsLock=1 where ComplainantApplicant_RelatedComplaintN_ID=v_ComplaintId and IsActive=1;
  
  -- -- Reminder Scheduler (Emails and SMS)  
  update tbl_rera_complaint_formn_reminderscheduler_emails set IsActive=2, D_Column=NOW() where RelatedComplaintFormN_ID=v_ComplaintId and IsActive=1 and FormN_Reminder_IndexID <> 0;
  update tbl_rera_complaint_formn_reminderscheduler_smsgateway set IsActive=2, D_Column=NOW() where RelatedComplaintFormN_ID=v_ComplaintId and IsActive=1 and FormN_ReminderSMS_IndexID <> 0;
 end if;
 
 -- Complaint TRANSFER between M and N (Transfer Request)
 If v_ComplaintEventType = 440063  
 then      
   update tbl_rera_complaint_formn_regdiarynumber set IsPublicView=1 where FormN_RelatedComplaint_ID=v_ComplaintId and ComplaintRegDiaryNumber_Name=v_ComplaintDiaryNumber and IsActive=1 and IsDraft=1;   
   
   update tbl_rera_complaint_formn_details set IsPublicView=1 where ComplaintFormN_ID=v_ComplaintId and IsActive=1 and IsLock=1; 
   update tbl_rera_complaint_formn_listenclosuresdocuments set IsPublicView=1 where ComplainantApplicant_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsLock=1; 
   update tbl_rera_complaint_formn_additioncomplainant set IsPublicView=1 where ComplainantorApplicant_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsLock=1; 
   update tbl_rera_complaint_formn_additionrespondent set IsPublicView=1 where AdditionRespondentM_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsLock=1;
   update tbl_rera_complaint_formn_document_factsofthecase set IsPublicView=1 where ComplainantApplicant_RelatedComplaintN_ID=v_ComplaintId and IsActive=1 and IsLock=1;
   
   update tbl_rera_complaint_formn_paymentgateway set IsPublicView=1 where PaymentComplaint_RelatedComplainant_ID=v_ComplaintId and isactive=1 and IsLock=1;
   
 end if;
 
  -- Complaint TRANSFER between M and N (Case Transfered)
 If v_ComplaintEventType = 440064  
 then
	update tbl_rera_complaint_formn_regdiarynumber set IsPublicView=1, IsActive=3 where FormN_RelatedComplaint_ID=v_ComplaintId and IsActive=1 and IsDraft=1;   
   
	Insert Into tbl_rera_complaint_formn_regdiarynumber
	(
		-- `ComplaintRegDiaryNumber_IndexID`,
		`ComplaintRegDiaryNumber_ID`,
		`ComplaintRegDiaryNumber_Name`,
		`ComplaintRegDiaryNumber_NameYear`,
		`FormN_RelatedComplaint_ID`,
		`FormN_RelatedComplaint_Code`,
		`Profile_ID`,
		`User_ID`,
		`ComplaintType_MN`,
		`IsComplaintComplete`,
		`IsPaymentComplete`,
		`PaymentTransactionID`,
		`PaymentTransactionDate`,
		`IsDocumentsComplete`,
		`DocumentUploadCount`,
		`IsVerificationComplete`,
		`ComplaintVerificationDate`,
		`CurrentEventcode`,
		`EventCodeDetails_indexID`,
		`Remarks_IfAny`,
		`A_column`,
		`B_column`,
		`C_column`,
		`IsActive`,
		`IsDraft`,
		`IsLock`,
		`IsPublicView`,
		`IsDraftHelpDesk`,
		`IsDraftEvaluation`,
		`IsDraftSecMember`,
		`IsDraftMember`,
		`CreatedBy`,
		`CreatedOn`,
		`ModifyBy`,
		`ModifyOn`
	)
	Select
		-- `ComplaintRegDiaryNumber_IndexID`,
		`ComplaintRegDiaryNumber_ID`,
		v_ComplaintDiaryNumber as `ComplaintRegDiaryNumber_Name`,
		`ComplaintRegDiaryNumber_NameYear`,
		`FormN_RelatedComplaint_ID`,
		`FormN_RelatedComplaint_Code`,
		`Profile_ID`,
		`User_ID`,
		`ComplaintType_MN`,
		`IsComplaintComplete`,
		`IsPaymentComplete`,
		`PaymentTransactionID`,
		`PaymentTransactionDate`,
		`IsDocumentsComplete`,
		`DocumentUploadCount`,
		`IsVerificationComplete`,
		`ComplaintVerificationDate`,
		`CurrentEventcode`,
		`EventCodeDetails_indexID`,
		`Remarks_IfAny`,
		`A_column`,
		`B_column`,
		`C_column`,
		1 as `IsActive`,
		1 as `IsDraft`,
		`IsLock`,
		1 as `IsPublicView`,
		`IsDraftHelpDesk`,
		`IsDraftEvaluation`,
		`IsDraftSecMember`,
		`IsDraftMember`,
		`CreatedBy`,
		NOW() as `CreatedOn`,
		`ModifyBy`,
		NOW() as `ModifyOn`
	from tbl_rera_complaint_formn_regdiarynumber
	where FormN_RelatedComplaint_ID=v_ComplaintId and IsActive=3 and IsDraft=1;
	-- order by ComplaintRegDiaryNumber_IndexID desc Limit 1;

	update tbl_rera_complaint_formn_regdiarynumber set IsActive=2 where FormN_RelatedComplaint_ID=v_ComplaintId and IsActive=3 and IsDraft=1;
   
 end if;
 
END */;;
